#include <cstddef>
#include <initializer_list>
#include <iostream>
#include <vector>

bool scan(const std::vector<int>& values, int target,
          std::size_t& examinations) {
    examinations = 0;
    for (std::size_t i = 0; i < values.size(); ++i) {
        ++examinations;
        if (values[i] == target) {
            return true;
        }
    }
    return false;
}

int main() {
    const std::vector<int> ids{2, 6, 9, 13, 18, 25, 34, 47};
    std::size_t examinations = 0;
    std::cout << std::boolalpha;
    for (int target : {25, 20}) {
        const bool found = scan(ids, target, examinations);
        std::cout << target << ": found=" << found
                  << ", examinations=" << examinations << '\n';
    }
    const bool found = scan({}, 25, examinations);
    std::cout << "empty: found=" << found
              << ", examinations=" << examinations << '\n';
}
